WITH base AS (
  SELECT "NCT", "PubMed ID" AS "PMID", "Author" AS "Author", "Year", "Cancer type", "Monotherapy/combination", "Type of combination"
  FROM compat.clinical_trials
  WHERE LOWER("Cancer type") LIKE '%head and neck%' AND LOWER("Monotherapy/combination") LIKE '%combination%'
)
SELECT * FROM base;
